    private final Periods periods;

    public Pools(JdbcTemplate jdbc, Settings settings, SheetClock clock, Periods periods) {
        this.jdbc = jdbc;
        this.settings = settings;
        this.clock = clock;
        this.periods = periods;
    }

    /**
